mapper.select:
SELECT id, chapter_id, group_code, title, order_index FROM edu.ccct_topics WHERE chapter_id IN
#{chapterId}
ORDER BY chapter_id, order_index

SELECT id, topic_id, content, order_index FROM edu.ccct_items WHERE topic_id IN
#{topicId}
ORDER BY topic_id, order_index

mapper.delete:
DELETE FROM edu.ccct_profiles
WHERE course_id = #{courseId}
  AND id = #{profileId}
  AND status = 'DRAFT'

mapper.update:
UPDATE edu.ccct_profiles
SET status = 'ARCHIVED',
    updated_at = NOW()
WHERE course_id = #{courseId}
  AND status = 'PUBLISHED'
  AND id = #{publishedProfileId}

UPDATE edu.ccct_profiles
SET status = 'PUBLISHED',
    published_at = #{publishedAt},
    version = version + 1,
    updated_at = NOW()
WHERE course_id = #{courseId}
  AND id = #{profileId}
  AND status = 'DRAFT'
  AND version = #{expectedVersion}
